 *
 * Since: 1.9.0
 */
void
hb_face_collect_unicodes (hb_face_t *face,
                          hb_set_t  *out)
{
  if (unlikely (!hb_ot_shaper_face_data_ensure (face))) return;
  hb_ot_face_data (face)->cmap->collect_unicodes (out);
}

